export function validateRegistry(
  entries: Publication[],
  lessons: readonly Lesson[],
) {
  if (new Set(entries.map((e) => e.lessonId)).size !== entries.length)
    throw new Error("发布清单课时 ID 重复");
  if (new Set(lessons.map((e) => e.id)).size !== lessons.length)
    throw new Error("内容课时 ID 重复");
  if (
    new Set(
      entries
        .filter((e) => e.catalogRole !== "legacy")
        .map((e) => `${e.chapterId}:${e.order}`),
    ).size !== entries.filter((e) => e.catalogRole !== "legacy").length
  )
    throw new Error("同章课时顺序重复");
  for (const entry of entries) {
    const catalog = getCourse(entry.courseId);
    const chapterIndex = catalog?.chapters.findIndex(
      (_, index) =>
        `${catalog.id}-C${String(index + 1).padStart(2, "0")}` ===
        entry.chapterId,
    );
    if (
      !catalog ||
      chapterIndex === undefined ||
      chapterIndex < 0 ||
      !entry.lessonId.startsWith(`${entry.chapterId}-L`)
    )
      throw new Error(`发布清单引用无效课程或章节：${entry.lessonId}`);
    if (entry.catalogRole !== "legacy") {
      const slot = courseOutline.find((s) => s.lessonId === entry.lessonId);
      if (
        !slot ||
        slot.chapterId !== entry.chapterId ||
        slot.title !== entry.title ||
        slot.order !== entry.order
      )
        throw new Error(`教材与节级蓝图不一致：${entry.lessonId}`);
    }
    const lesson = lessons.find((l) => l.id === entry.lessonId);
    if (!lesson) throw new Error(`缺少教材：${entry.lessonId}`);
    for (const key of [
      "courseId",
      "chapterId",
      "title",
      "contentVersion",
    ] as const)
      if (lesson[key] !== entry[key])
        throw new Error(`教材与清单不一致：${entry.lessonId}.${key}`);
  }
  for (const lesson of lessons)
    if (!entries.some((e) => e.lessonId === lesson.id))
      throw new Error(`教材未登记：${lesson.id}`);
}
validateRegistry(publicationManifest, contents);

export function getLearningCourse(courseId: string): Course | undefined {
  const catalog = getCourse(courseId);
  if (!catalog) return undefined;
  return getCourseDirectory(catalog);
}
export function resolveLesson(courseId: string, lessonId: string) {
  const publication = publicationManifest.find(
    (e) => e.courseId === courseId && e.lessonId === lessonId,
  );
  if (!publication || !isReadable(publication)) return undefined;
  const course = getLearningCourse(courseId);
  const lesson = lessonRegistry.get(lessonId);
  const chapter = course?.chapters.find((c) => c.id === publication.chapterId);
  return course && lesson && chapter
    ? { course, chapter, lesson, publication }
    : undefined;
}
export function getAdjacentLessons(course: Course, lessonId: string) {
  const lessons = course.chapters
    .flatMap((c) => c.lessons)
    .filter((e) => e.catalogRole !== "legacy" && isReadable(e));
  const index = lessons.findIndex((l) => l.lessonId === lessonId);
  if (index < 0) return {};
  return { previous: lessons[index - 1], next: lessons[index + 1] };
}
export const lessonSummaries: LessonSummary[] = readablePublications.map(
  (entry) => ({
    ...entry,
    href: lessonHref(entry),
    courseName: getCourse(entry.courseId)!.name,
    level: getCourse(entry.courseId)!.lvl,
    displayNumber: getLearningCourse(entry.courseId)
      ?.chapters.flatMap((ch) => ch.lessons)
      .find((l) => l.lessonId === entry.lessonId)?.displayNumber,
    sectionTitles: lessonRegistry
      .get(entry.lessonId)!
      .sections.map(({ id, title }) => ({ id, title })),
  }),
);
export const learningCourses = courses.map((c) => getLearningCourse(c.id)!);

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";

type SourceChange = { path: string; before: string; afterSha256: string };
type ObjectChange = { id: string; before: unknown; afterSha256: string };
// 使用同一个登记器按新到旧撤销已批准修订；不为每轮再嵌套一个专用兼容器。
const approved = JSON.parse(readFileSync(new URL("../docs/py101-p2/APPROVED_CHANGES.json", import.meta.url), "utf8")) as { sources: SourceChange[]; lessons: ObjectChange[]; publications: ObjectChange[]; addedLessonIds: string[]; workspaceOnly: { path: string; workspaceSha256: string; repositorySha256: string }[]; protectedText: { path: string; baselineSha256: string; lfSha256: string }[] };
const sources = JSON.parse(readFileSync(new URL("../docs/py101-p1/SOURCE_CHANGES.json", import.meta.url), "utf8")) as SourceChange[];
const sha = (source: string) => createHash("sha256").update(source).digest("hex");
function undoSource(entries: SourceChange[], path: string, source: string) {
  const entry = entries.find(row => row.path === path);
  return entry && sha(source.replaceAll("\r\n", "\n")) === entry.afterSha256 ? entry.before : source;
}
export const approvedPy101Additions = approved.addedLessonIds;
export function beforeApprovedPy101Source(path: string, source: string) { return undoSource(approved.sources, path, source); }
// 自动回归允许原工作区与干净检出两种精确版本；工作区审计脚本仍严格要求原始指纹。
export function protectedPy101FileMatches(path: string, bytes: Buffer, expected: string) {
  const digest = createHash("sha256").update(bytes).digest("hex");
  if (digest === expected) return true;
  const text = bytes.toString("utf8");
  // Git检出可转换文本换行；二进制仍逐字节比较，绝不以UTF-8解码后的图像作摘要。
  const validText = !text.includes("\0") && Buffer.from(text).equals(bytes);
  const variants = (value: string) => { const lf = value.replaceAll("\r\n", "\n"); return [lf, lf.replaceAll("\n", "\r\n")]; };
  const matches = (value: string, target: string) => validText && variants(value).some(source => sha(source) === target);
  if (matches(text, expected)) return true;
  const portable = approved.protectedText.find(row => row.path === path && row.baselineSha256 === expected);
  if (portable && validText && sha(text.replaceAll("\r\n", "\n")) === portable.lfSha256) return true;
  const local = approved.workspaceOnly.find(row => row.path === path);
  if (local?.workspaceSha256 === expected && (local.repositorySha256 === digest || matches(text, local.repositorySha256))) return true;
  return matches(beforeApprovedPy101Source(path, text), expected);
}
export function beforeApprovedPy101Object(kind: "lessons" | "publications", id: string, value: unknown) {
  const entry = approved[kind].find(row => row.id === id);
  return entry && sha(JSON.stringify(value)) === entry.afterSha256 ? entry.before : value;
}
// 只有完整文件摘要命中才还原；未登记的任何附加修改必须继续暴露给旧保护测试。
export function beforePy101P1Source(path: string, source: string) {
  return undoSource(sources, path, beforeApprovedPy101Source(path, source));
}

import { spawnSync } from "node:child_process";
import { writeFile } from "node:fs/promises";
import { evidencePath } from "./evidence-path";
import { lessonRegistry } from "../src/lib/course-engine";
import { corePrograms, regressionCoreCode } from "../src/content/resources/core-programs";
import { programs, gradientDescentCode } from "../src/content/resources/programs";

const python = process.env.AIVORA_PYTHON ?? "python";
function run(args: string[]) {
  const result = spawnSync(python, args, {
    encoding: "utf8",
    env: { ...process.env, PYTHONIOENCODING: "utf-8" },
    timeout: 30_000,
  });
  if (result.error || result.status !== 0)
    throw new Error(`Python 校验失败：${result.error ?? result.stderr}`);
  return {
    exitCode: result.status,
    stdout: result.stdout.replace(/\r\n/g, "\n").trim(),
    stderr: result.stderr.replace(/\r\n/g, "\n").trim(),
  };
}
const environment = run([
  "-c",
  "import sys,numpy; print(sys.version.split()[0]); print('NumPy',numpy.__version__)",
]);
const unit = run([
  "-m",
  "unittest",
  "discover",
  "-s",
  "tests",
  "-p",
  "test_*.py",
  "-v",
]);
const examples = [...lessonRegistry.values()].flatMap((lesson) =>
  lesson.sections.flatMap((section) =>
    section.blocks.flatMap((block) => {
      if (block.type !== "code" || block.language !== "python") return [];
      const result = run(["-c", block.code]);
      const expected = ({ "第一条Python指令": "Hello, Aivora!", "first_run.py": "Hello, Aivora!\nFile: first_run.py", "read_vector_components.py": "4 0 7", "add_two_vectors.py": "[2, 3]", "scale_vector.py": "[-6, -4]", "double_without_function.py":"6", "double_definition.py":"", "one_update.py":"-13.0 -8.0 1.3 0.8 1.685", "one_update_checks.py":"-13.0 -8.0 1.3 0.8 1.685" } as Record<string,string>)[block.filename];
      if (expected !== undefined && result.stdout !== expected)
        throw new Error(`教材输出与预期不一致：${block.filename}`);
      return [
        {
          lessonId: lesson.id,
          sectionId: section.id,
          filename: block.filename,
          ...(expected !== undefined ? { expected } : {}),
          ...result,
        },
      ];
    }),
  ),
);
const expectedOutputs: Record<keyof typeof corePrograms, string> = {
  "function-basics": "6", "function-binding": "12\n12", "function-return": "4\n4 None",
  "function-scope": "5\n10", "function-defaults": "6\n12", "vector-basics": "[4, 3] [2, 4]",
  "vector-dot": "5", "matrix-shape": "[[1, 4], [2, 5], [3, 6]]",
  "matrix-product": "[[4 6]\n [1 3]]", "numpy-shapes": "(2,) (2,)\n(2, 1) (1, 2)\n5",
};
const coreComparisons = Object.entries(corePrograms).map(([id, sample]) => {
  const core = run(["-c", sample.core + "\n" + sample.checks]);
  const full = run(["-c", programs[id as keyof typeof corePrograms].code]);
  if (core.stdout !== expectedOutputs[id as keyof typeof corePrograms] || core.stdout !== full.stdout)
    throw new Error(`核心/完整版输出与预期不一致：${id}`);
  return { id, expected: expectedOutputs[id as keyof typeof corePrograms], ...core, fullMatches: true };
});
const trainingComparison = run(["-c", `import numpy as np
core, full = {}, {}
exec(${JSON.stringify(regressionCoreCode)}, core)
exec(${JSON.stringify(gradientDescentCode)}, full)
np.testing.assert_allclose([core['w'], core['b'], core['final_loss']], [full['w'], full['b'], full['final_loss']], atol=1e-12, rtol=0)
np.testing.assert_allclose([core['w'], core['b']], [2,1], atol=1e-7, rtol=0)
assert core['final_loss'] < 1e-10
print('core/full training match; independent expected line y=2x+1')
`]);
const report = {
  checkedAt: new Date().toISOString(),
  environment: environment.stdout,
  unittest: unit,
  examples,
  coreComparisons,
  trainingComparison,
  note: "技术校验通过；不代表人工内容审核、试学或正式发布。代码来自仓库静态教材，仅开发阶段执行。",
};
const reportPath = evidencePath("TEACHING_V2_3_PYTHON_RESULTS.json");
await writeFile(
  reportPath,
  JSON.stringify(report, null, 2) + "\n",
);
console.log(
  `Python 单元测试通过，${examples.length} 个网页代码块全部实际执行通过，${coreComparisons.length} 组核心/完整版一致。证据：${reportPath}`,
);

import test from "node:test";
import assert from "node:assert/strict";
